#include<bits/stdc++.h>

using namespace std;

int f(int n){
  string s=to_string(n);
  int res=0;
  for(auto &nx : s){
    res+=(nx-'0')*(nx-'0');
  }
  return res;
}

int main(){
  int n;
  cin >> n;
  set<int> history;
  while(n>1){
    if(history.find(n)!=history.end()){
      cout << "No\n";
      return 0;
    }
    history.insert(n);
    n=f(n);
  }
  cout << "Yes\n";
  return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 操作の結果を得る関数
    auto next = [](auto x){
        int ret = 0;
        do
            ret += (x % 10) * (x % 10);
        while (x /= 10);
        return ret;
    };

    int N;
    cin >> N;

    // 1 か 4 に到達するまで操作して
    while (N != 1 && N != 4)
        N = next(N);
    // 1 なら Yes 、4 なら No
    cout << (N == 1 ? "Yes" : "No") << endl;
    return 0;
}
